import math
from collections.abc import Mapping

def most_correlated_columns(data):
    if not isinstance(data, Mapping):
        raise TypeError("data must be a mapping of column names to lists of numbers")
    if not data or len(data) < 2:
        raise ValueError("At least two columns are required")

    names = list(data.keys())
    columns = []
    length = None

    for name, col in data.items():
        try:
            values = list(col)
        except TypeError as exc:
            raise TypeError(f"Column {name!r} is not a sequence of numbers") from exc

        if length is None:
            length = len(values)
        elif len(values) != length:
            raise ValueError("All columns must have the same length")

        numeric = []
        for value in values:
            if isinstance(value, (str, bytes, bytearray)):
                raise TypeError(f"Column {name!r} contains non-numeric values")
            try:
                numeric.append(float(value))
            except (TypeError, ValueError) as exc:
                raise TypeError(f"Column {name!r} contains non-numeric values") from exc
        columns.append(numeric)

    if length == 0:
        raise ValueError("No data")

    means = [sum(col) / length for col in columns]
    best_pair = (names[0], names[1])
    best_abs = -1.0

    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            x = columns[i]
            y = columns[j]
            mean_x = means[i]
            mean_y = means[j]

            sxx = syy = sxy = 0.0
            for xv, yv in zip(x, y):
                dx = xv - mean_x
                dy = yv - mean_y
                sxx += dx * dx
                syy += dy * dy
                sxy += dx * dy

            if sxx == 0.0 or syy == 0.0:
                corr = 0.0
            else:
                corr = sxy / math.sqrt(sxx * syy)
                if not math.isfinite(corr):
                    corr = 0.0

            abs_corr = abs(corr)
            if abs_corr > best_abs:
                best_abs = abs_corr
                best_pair = (names[i], names[j])

    return best_pair
