import random


def kmeans_centers(points, n_clusters):
    if not points:
        raise ValueError("points must not be empty")
    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")
    if n_clusters > len(points):
        raise ValueError("n_clusters cannot exceed the number of points")

    try:
        k = int(n_clusters)
    except (TypeError, ValueError):
        raise ValueError("n_clusters must be an integer")

    if k != n_clusters:
        raise ValueError("n_clusters must be an integer")

    pts = [(float(x), float(y)) for x, y in points]

    if k == len(pts):
        return [[x, y] for x, y in sorted(pts)]

    if k == 1:
        sx = sum(p[0] for p in pts)
        sy = sum(p[1] for p in pts)
        n = len(pts)
        return [[sx / n, sy / n]]

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def initial_centers(seed):
        rng = random.Random(seed)
        first = rng.randrange(len(pts))
        centers = [pts[first]]
        chosen = {first}

        for _ in range(1, k):
            d2 = []
            total = 0.0
            for p in pts:
                d = min(dist2(p, c) for c in centers)
                d2.append(d)
                total += d

            if total <= 1e-15:
                remaining = [i for i in range(len(pts)) if i not in chosen]
                if not remaining:
                    remaining = list(range(len(pts)))
                idx = remaining[rng.randrange(len(remaining))]
            else:
                r = rng.random() * total
                acc = 0.0
                idx = len(pts) - 1
                for i, d in enumerate(d2):
                    acc += d
                    if acc >= r:
                        idx = i
                        break

            centers.append(pts[idx])
            chosen.add(idx)

        return [[c[0], c[1]] for c in centers]

    def run_kmeans(initial):
        centers = [[float(c[0]), float(c[1])] for c in initial]

        for _ in range(200):
            assignments = []
            for p in pts:
                best_idx = 0
                best_d = dist2(p, centers[0])
                for i in range(1, k):
                    d = dist2(p, centers[i])
                    if d < best_d:
                        best_d = d
                        best_idx = i
                assignments.append(best_idx)

            sums_x = [0.0] * k
            sums_y = [0.0] * k
            counts = [0] * k

            for p, a in zip(pts, assignments):
                counts[a] += 1
                sums_x[a] += p[0]
                sums_y[a] += p[1]

            new_centers = [None] * k
            for i in range(k):
                if counts[i] > 0:
                    new_centers[i] = [
                        sums_x[i] / counts[i],
                        sums_y[i] / counts[i],
                    ]

            empty = [i for i, c in enumerate(new_centers) if c is None]
            if empty:
                used = set()
                for i in empty:
                    best_j = 0
                    best_d = -1.0
                    for j, p in enumerate(pts):
                        if j in used:
                            continue
                        d = dist2(p, centers[assignments[j]])
                        if d > best_d:
                            best_d = d
                            best_j = j
                    used.add(best_j)
                    new_centers[i] = [pts[best_j][0], pts[best_j][1]]

            shift = max(dist2(centers[i], new_centers[i]) for i in range(k))
            centers = new_centers

            if shift <= 1e-20:
                break

        return centers

    def inertia(centers):
        total = 0.0
        for p in pts:
            total += min(dist2(p, c) for c in centers)
        return total

    best = None
    best_inertia = float("inf")

    for seed in range(10):
        centers = run_kmeans(initial_centers(seed))
        value = inertia(centers)

        if value < best_inertia - 1e-12:
            best_inertia = value
            best = centers
        elif abs(value - best_inertia) <= 1e-12:
            if best is None or sorted(centers) < sorted(best):
                best = centers
                best_inertia = value

    return sorted([[float(x), float(y)] for x, y in best])
