def fit_linear_regression(features, values):
    if len(features) != len(values):
        raise ValueError("features and values must have the same length")
    if not features:
        raise ValueError("at least one sample is required")

    num_samples = len(features)
    num_features = len(features[0])

    for row in features:
        if len(row) != num_features:
            raise ValueError("all feature rows must have the same length")

    n = num_features + 1  # include intercept
    XtX = [[0.0] * n for _ in range(n)]
    Xty = [0.0] * n

    for row, target in zip(features, values):
        x = [1.0] + [float(v) for v in row]
        y = float(target)

        for i in range(n):
            Xty[i] += x[i] * y
            for j in range(i, n):
                XtX[i][j] += x[i] * x[j]

    for i in range(n):
        for j in range(i):
            XtX[i][j] = XtX[j][i]

    # Solve (X^T X) beta = X^T y using Gauss-Jordan elimination.
    A = [XtX[i] + [Xty[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(A[r][col]))

        if abs(A[pivot][col]) < 1e-12:
            raise ValueError("linear regression is singular")

        if pivot != col:
            A[col], A[pivot] = A[pivot], A[col]

        divisor = A[col][col]
        for j in range(col, n + 1):
            A[col][j] /= divisor

        for row in range(n):
            if row == col:
                continue

            factor = A[row][col]
            if abs(factor) > 1e-15:
                for j in range(col, n + 1):
                    A[row][j] -= factor * A[col][j]

    beta = [A[i][n] for i in range(n)]

    return {
        "coefficients": beta[1:],
        "intercept": float(beta[0])
    }
