import csv
import io
import re

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(
    r"^[+-]?(?:(?:\d+\.\d*|\.\d+)(?:[eE][+-]?\d+)?|\d+[eE][+-]?\d+)$"
)


def _convert_cell(cell):
    if cell == "":
        return None

    stripped = cell.strip()

    if stripped == "":
        return cell

    if _INT_RE.fullmatch(stripped):
        return int(stripped)

    if _FLOAT_RE.fullmatch(stripped):
        return float(stripped)

    return cell


def merge_csv_texts(csv_texts):
    if not csv_texts:
        return []

    all_columns = []
    seen_columns = set()
    parsed_files = []

    for text in csv_texts:
        reader = csv.reader(io.StringIO(text, newline=""))

        try:
            header = next(reader)
        except StopIteration:
            continue

        for column in header:
            if column not in seen_columns:
                seen_columns.add(column)
                all_columns.append(column)

        parsed_files.append((header, list(reader)))

    result = []

    for header, rows in parsed_files:
        for row in rows:
            if len(row) == 0:
                continue

            item = {column: None for column in all_columns}

            for index, column in enumerate(header):
                if index < len(row):
                    item[column] = _convert_cell(row[index])
                else:
                    item[column] = None

            result.append(item)

    return result
