import math

def five_column_correlation_matrix(array):
    if not array:
        raise ValueError("Input array must not be empty")

    for row in array:
        if len(row) != 5:
            raise ValueError("Each row must contain exactly 5 values")

    n = len(array)
    columns = [[float(row[j]) for row in array] for j in range(5)]

    means = [sum(col) / n for col in columns]

    centered = []
    sum_squares = []

    for col, mean in zip(columns, means):
        centered_col = [value - mean for value in col]
        centered.append(centered_col)
        sum_squares.append(sum(value * value for value in centered_col))

    result = [[0.0] * 5 for _ in range(5)]

    for i in range(5):
        for j in range(5):
            if i == j:
                result[i][j] = 1.0 if sum_squares[i] > 0.0 else float("nan")
                continue

            denominator = math.sqrt(sum_squares[i] * sum_squares[j])

            if denominator == 0.0:
                result[i][j] = float("nan")
            else:
                numerator = sum(
                    centered[i][k] * centered[j][k]
                    for k in range(n)
                )
                result[i][j] = numerator / denominator

    return result
