import csv
import io
import math


def predict_linear_regression(train_csv, test_csv, target):
    def read_rows(text):
        reader = csv.reader(io.StringIO(text))
        try:
            header = next(reader)
        except StopIteration:
            raise ValueError("empty CSV")
        rows = list(reader)
        return header, rows

    def parse_number(value):
        if value is None:
            raise ValueError("missing value")
        value = value.strip()
        if value == "":
            raise ValueError("missing value")
        try:
            number = float(value)
        except (TypeError, ValueError):
            raise ValueError("non-numeric value")
        if not math.isfinite(number):
            raise ValueError("non-numeric value")
        return number

    train_header, train_rows = read_rows(train_csv)
    test_header, test_rows = read_rows(test_csv)

    if target not in train_header:
        raise ValueError("target column not found")

    target_idx = train_header.index(target)
    feature_names = [
        name for i, name in enumerate(train_header) if i != target_idx
    ]

    test_columns = {}
    for i, name in enumerate(test_header):
        if name not in test_columns:
            test_columns[name] = i

    for name in feature_names:
        if name not in test_columns:
            raise ValueError("missing feature column in test data")

    test_feature_indices = [test_columns[name] for name in feature_names]

    X = []
    y = []

    for row in train_rows:
        features = []
        for i in range(len(train_header)):
            if i == target_idx:
                continue
            if i >= len(row):
                raise ValueError("missing value")
            features.append(parse_number(row[i]))

        if target_idx >= len(row):
            raise ValueError("missing value")

        y.append(parse_number(row[target_idx]))
        X.append(features)

    X_test = []
    for row in test_rows:
        features = []
        for idx in test_feature_indices:
            if idx >= len(row):
                raise ValueError("missing value")
            features.append(parse_number(row[idx]))
        X_test.append(features)

    if not X:
        raise ValueError("no training data")

    num_features = len(feature_names)
    num_params = num_features + 1

    # Compute X^T X and X^T y for the design matrix with intercept.
    ATA = [[0.0] * num_params for _ in range(num_params)]
    ATy = [0.0] * num_params

    for features, y_value in zip(X, y):
        row = [1.0] + features
        for j in range(num_params):
            ATy[j] += row[j] * y_value
            for k in range(j, num_params):
                ATA[j][k] += row[j] * row[k]

    for j in range(num_params):
        for k in range(j):
            ATA[j][k] = ATA[k][j]

    # Solve ATA * beta = ATy using Gaussian elimination.
    matrix = [ATA[i] + [ATy[i]] for i in range(num_params)]

    for col in range(num_params):
        pivot_row = max(range(col, num_params), key=lambda r: abs(matrix[r][col]))
        scale = max(1.0, max(abs(matrix[r][col]) for r in range(col, num_params)))
        if abs(matrix[pivot_row][col]) < 1e-12 * scale:
            raise ValueError("singular matrix in linear regression")

        if pivot_row != col:
            matrix[col], matrix[pivot_row] = matrix[pivot_row], matrix[col]

        pivot = matrix[col][col]
        for j in range(col, num_params + 1):
            matrix[col][j] /= pivot

        for r in range(num_params):
            if r == col:
                continue
            factor = matrix[r][col]
            if factor != 0.0:
                for j in range(col, num_params + 1):
                    matrix[r][j] -= factor * matrix[col][j]

    beta = [matrix[i][num_params] for i in range(num_params)]

    predictions = []
    for features in X_test:
        prediction = beta[0]
        for j, value in enumerate(features, start=1):
            prediction += beta[j] * value
        predictions.append(float(prediction))

    return predictions
