import math

def remove_zscore_outliers(rows, column, threshold):
    if not rows:
        return [], []

    values = [row[column] for row in rows]
    n = len(values)

    mean = sum(values) / n
    variance = sum((x - mean) ** 2 for x in values) / n
    std = math.sqrt(variance)

    kept = []
    outliers = []

    for i, row in enumerate(rows):
        if std == 0:
            z = 0.0
        else:
            z = (row[column] - mean) / std

        if abs(z) > threshold:
            outliers.append(i)
        else:
            kept.append(row)

    return kept, outliers
