import math

def standardize_columns(data):
    result = {}

    for name, values in data.items():
        present = [v for v in values if v is not None]

        if present:
            fill_mean = sum(present) / len(present)
        else:
            fill_mean = 0.0

        filled = [fill_mean if v is None else v for v in values]

        if not filled:
            result[name] = []
            continue

        mean = sum(filled) / len(filled)
        variance = sum((v - mean) ** 2 for v in filled) / len(filled)
        std = math.sqrt(variance)

        if std == 0:
            result[name] = [0.0 for _ in filled]
        else:
            result[name] = [(v - mean) / std for v in filled]

    return result
