from html.parser import HTMLParser


class _DataTableExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found = False
        self.done = False
        self.depth = 0

        self.rows = []
        self.current_row = None
        self.current_cell = None
        self.cell_depth = None
        self.row_depth = None

    def _close_cell(self):
        if self.current_cell is not None:
            if self.current_row is not None:
                self.current_row.append("".join(self.current_cell))
            self.current_cell = None
            self.cell_depth = None

    def _close_row(self):
        if self.current_cell is not None:
            self._close_cell()
        if self.current_row is not None:
            self.rows.append(self.current_row)
            self.current_row = None
        self.row_depth = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        tag = tag.lower()

        if not self.found:
            if tag == "table":
                for name, value in attrs:
                    if name == "class" and value == "data-table":
                        self.found = True
                        self.depth = 1
                        break
            return

        if tag == "table":
            self.depth += 1
            return

        if self.depth == 1:
            if tag == "tr":
                if self.current_cell is not None or self.current_row is not None:
                    self._close_row()
                self.current_row = []
                self.row_depth = 1

            elif tag == "td":
                if self.current_row is not None:
                    if self.current_cell is not None:
                        self._close_cell()
                    self.current_cell = []
                    self.cell_depth = 1

    def handle_endtag(self, tag):
        if self.done or not self.found:
            return

        tag = tag.lower()

        if tag == "table":
            if self.depth == 1:
                if self.current_cell is not None or self.current_row is not None:
                    self._close_row()
                self.depth -= 1
                if self.depth == 0:
                    self.done = True
            else:
                self.depth -= 1
            return

        if self.depth == 1:
            if tag == "td":
                if self.current_cell is not None and self.cell_depth == 1:
                    self._close_cell()

            elif tag == "tr":
                if self.current_row is not None and self.row_depth == 1:
                    if self.current_cell is not None and self.cell_depth == 1:
                        self._close_cell()
                    self._close_row()

    def handle_data(self, data):
        if self.found and not self.done and self.current_cell is not None:
            self.current_cell.append(data)

    def finish(self):
        if self.found and not self.done:
            if self.current_cell is not None or self.current_row is not None:
                self._close_row()
            self.done = True


def extract_data_table_rows(html):
    parser = _DataTableExtractor()
    parser.feed(html)
    parser.close()
    parser.finish()
    return parser.rows
```

