from html.parser import HTMLParser


class _Node:
    __slots__ = ("tag", "attrs", "children")

    def __init__(self, tag, attrs=None):
        self.tag = tag
        self.attrs = attrs or {}
        self.children = []


class _TreeBuilder(HTMLParser):
    _VOID_TAGS = {
        "area", "base", "br", "col", "embed", "hr", "img", "input",
        "link", "meta", "param", "source", "track", "wbr",
    }

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node(None)
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        node = _Node(tag, dict(attrs))
        self.stack[-1].children.append(node)
        if tag not in self._VOID_TAGS:
            self.stack.append(node)

    def handle_startendtag(self, tag, attrs):
        node = _Node(tag, dict(attrs))
        self.stack[-1].children.append(node)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, 0, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        self.stack[-1].children.append(data)


def _classes(node):
    value = node.attrs.get("class")
    return set(value.split()) if value else set()


def _text(node):
    parts = []

    def walk(current):
        for child in current.children:
            if isinstance(child, _Node):
                walk(child)
            else:
                parts.append(child)

    walk(node)
    return "".join(parts).strip()


def _find_first(node, tag, required_classes=None):
    required_classes = required_classes or set()

    for child in node.children:
        if not isinstance(child, _Node):
            continue

        if child.tag == tag and required_classes.issubset(_classes(child)):
            return child

        found = _find_first(child, tag, required_classes)
        if found is not None:
            return found

    return None


def extract_article_info(html):
    parser = _TreeBuilder()
    parser.feed(html)
    parser.close()

    result = []

    def visit(node):
        for child in node.children:
            if not isinstance(child, _Node):
                continue

            if child.tag == "div" and "container" in _classes(child):
                title_node = _find_first(child, "h1")
                date_node = _find_first(child, "span", {"date"})
                author_node = _find_first(child, "span", {"author"})

                title = _text(title_node) if title_node is not None else "No Title"
                date = _text(date_node) if date_node is not None else "No Date"
                author = _text(author_node) if author_node is not None else "No Author"

                result.append((title, date, author))

            visit(child)

    visit(parser.root)
    return result
