def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    if len(train_X) == 0 or len(train_y) == 0:
        raise ValueError("training set is empty")
    if len(train_X) != len(train_y):
        raise ValueError("train_X and train_y must have the same length")
    if len(test_X) != len(test_y):
        raise ValueError("test_X and test_y must have the same length")

    n = len(train_X)
    p = len(train_X[0])
    d = p + 1  # intercept plus features

    # Normal equations: (A^T A) beta = A^T y
    M = [[0.0] * (d + 1) for _ in range(d)]

    for i in range(n):
        row = train_X[i]
        phi = [1.0] + [float(v) for v in row]
        y = float(train_y[i])

        for j in range(d):
            for k in range(d):
                M[j][k] += phi[j] * phi[k]
            M[j][d] += phi[j] * y

    # Solve the normal equations using reduced row echelon form.
    row = 0
    pivots = []
    eps = 1e-12

    for col in range(d):
        if row >= d:
            break

        pivot = row
        best = abs(M[row][col])

        for r in range(row + 1, d):
            value = abs(M[r][col])
            if value > best:
                best = value
                pivot = r

        if best < eps:
            continue

        if pivot != row:
            M[row], M[pivot] = M[pivot], M[row]

        divisor = M[row][col]
        for c in range(col, d + 1):
            M[row][c] /= divisor

        for r in range(d):
            if r == row:
                continue

            factor = M[r][col]
            if abs(factor) < eps:
                continue

            for c in range(col, d + 1):
                M[r][c] -= factor * M[row][c]

        pivots.append(col)
        row += 1

    beta = [0.0] * d
    for r, col in enumerate(pivots):
        beta[col] = M[r][d]

    if len(test_X) == 0:
        return 1.0

    predictions = []
    for sample in test_X:
        pred = beta[0]
        for j, x in enumerate(sample):
            if j + 1 < d:
                pred += beta[j + 1] * float(x)
        predictions.append(pred)

    y_test = [float(y) for y in test_y]
    mean_y = sum(y_test) / len(y_test)

    ss_tot = sum((y - mean_y) ** 2 for y in y_test)
    ss_res = sum(
        (y_test[i] - predictions[i]) ** 2
        for i in range(len(y_test))
    )

    if ss_tot == 0.0:
        return 1.0 if ss_res < eps else 0.0

    return float(1.0 - ss_res / ss_tot)
```

