import math

def standardize_columns(rows, columns):
    rows = list(rows)
    n = len(rows)

    if n == 0:
        return {col: [] for col in columns}

    result = {}

    for j, col in enumerate(columns):
        values = [row[j] for row in rows]

        # Constant column becomes all zeros
        if all(v == values[0] for v in values):
            result[col] = [0.0] * n
            continue

        mean = sum(values) / n
        deviations = [v - mean for v in values]
        variance = sum(d * d for d in deviations) / n
        std = math.sqrt(variance)

        if std == 0:
            result[col] = [0.0] * n
        else:
            result[col] = [d / std for d in deviations]

    return result
