def seasonal_decomposition(values, period, model):
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if period <= 0:
        raise ValueError("period must be positive")

    n = len(values)
    if n < 2 * period:
        raise ValueError("series must contain at least two complete periods")

    trend = [None] * n

    if period % 2 == 1:
        half = period // 2
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:
        half = period // 2
        for i in range(half, n - half):
            total = 0.5 * values[i - half] + 0.5 * values[i + half]
            total += sum(values[i - half + 1:i + half])
            trend[i] = total / period

    phase_values = [[] for _ in range(period)]

    for i, tr in enumerate(trend):
        if tr is None:
            continue

        if model == "additive":
            detrended = values[i] - tr
        else:
            detrended = values[i] / tr

        phase_values[i % period].append(detrended)

    phase_means = [
        sum(vals) / len(vals) if vals else (0.0 if model == "additive" else 1.0)
        for vals in phase_values
    ]

    if model == "additive":
        adjustment = sum(phase_means) / period
        phase_seasonal = [x - adjustment for x in phase_means]
    else:
        adjustment = sum(phase_means) / period
        phase_seasonal = [x / adjustment for x in phase_means]

    seasonal = [phase_seasonal[i % period] for i in range(n)]

    residual = [None] * n
    for i, tr in enumerate(trend):
        if tr is None:
            continue

        if model == "additive":
            residual[i] = values[i] - tr - seasonal[i]
        else:
            residual[i] = values[i] / (tr * seasonal[i])

    return {
        "trend": trend,
        "seasonal": seasonal,
        "residual": residual,
    }
