def weather_column_summary(column, data):
    column_indices = {
        'Temperature': 1,
        'Humidity': 2,
        'Wind Speed': 3,
        'Precipitation': 4,
    }

    index = column_indices[column]
    values = [row[index] for row in data]

    if not values:
        return {
            'sum': 0,
            'mean': None,
            'min': None,
            'max': None,
            'histogram': [0] * 10,
        }

    total = sum(values)
    min_val = min(values)
    max_val = max(values)
    histogram = [0] * 10

    if min_val == max_val:
        histogram[9] = len(values)
    else:
        bin_width = (max_val - min_val) / 10

        for value in values:
            if value == max_val:
                bin_index = 9
            else:
                bin_index = int((value - min_val) / bin_width)
                bin_index = min(max(bin_index, 0), 9)

            histogram[bin_index] += 1

    return {
        'sum': total,
        'mean': total / len(values),
        'min': min_val,
        'max': max_val,
        'histogram': histogram,
    }
