import math

def zscore_normalize_columns(matrix):
    if not matrix:
        return []

    num_rows = len(matrix)
    num_cols = len(matrix[0])

    if num_cols == 0:
        return [[] for _ in range(num_rows)]

    means = [
        sum(matrix[i][j] for i in range(num_rows)) / num_rows
        for j in range(num_cols)
    ]

    stds = []
    for j in range(num_cols):
        mean = means[j]
        variance = sum((matrix[i][j] - mean) ** 2 for i in range(num_rows)) / num_rows
        stds.append(math.sqrt(variance))

    result = []
    for i in range(num_rows):
        new_row = []
        for j in range(num_cols):
            if stds[j] == 0:
                new_row.append(0.0)
            else:
                new_row.append((matrix[i][j] - means[j]) / stds[j])
        result.append(new_row)

    return result
