import csv
import io
import re

_INT_RE = re.compile(r'^[+-]?\d+$')
_NUMBER_RE = re.compile(
    r'^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$'
)


def _is_number(value):
    return isinstance(value, str) and _NUMBER_RE.fullmatch(value.strip()) is not None


def _to_number(value):
    value = value.strip()
    if _INT_RE.fullmatch(value):
        return int(value)
    return float(value)


def sort_csv_rows(csv_text, sort_by_column='title'):
    reader = csv.DictReader(io.StringIO(csv_text))
    fieldnames = reader.fieldnames
    if fieldnames is None:
        return []

    rows = list(reader)
    if not rows:
        return []

    # Detect columns where every value is numeric, and convert those columns.
    for column in fieldnames:
        if all(_is_number(row.get(column)) for row in rows):
            for row in rows:
                row[column] = _to_number(row[column])

    return sorted(rows, key=lambda row: row[sort_by_column])
