from numbers import Real

def normalized_cumulative_sums(data):
    if not data:
        raise ValueError("data is empty")

    if any(len(values) == 0 for values in data.values()):
        raise ValueError("data is empty")

    # Validate types first so non-numeric values raise TypeError.
    for values in data.values():
        for value in values:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise TypeError("all values must be numeric")

    # Reject NaN values.
    for values in data.values():
        for value in values:
            if value != value:  # True for NaN
                raise ValueError("data contains NaN")

    result = {}

    for name, values in data.items():
        cumulative = []
        running_sum = 0

        for value in values:
            running_sum += value
            cumulative.append(running_sum)

        minimum = min(cumulative)
        maximum = max(cumulative)

        if maximum == minimum:
            result[name] = [0.0] * len(cumulative)
        else:
            denominator = maximum - minimum
            result[name] = [
                float((value - minimum) / denominator)
                for value in cumulative
            ]

    return result
