from xml.etree import ElementTree as ET


def xml_to_dict(xml):
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError(f"Malformed XML: {exc}") from None

    def direct_text(element):
        parts = []
        if element.text:
            parts.append(element.text)
        for child in element:
            if child.tail:
                parts.append(child.tail)
        text = "".join(parts).strip()
        return text if text else None

    def convert(element):
        attrs = {"@" + key: value for key, value in element.attrib.items()}
        children = list(element)

        # Leaf element: return only its text.
        if not attrs and not children:
            if element.text is None:
                return None
            text = element.text.strip()
            return text if text else None

        result = {}
        result.update(attrs)

        for child in children:
            tag = child.tag
            value = convert(child)

            if tag in result:
                if isinstance(result[tag], list):
                    result[tag].append(value)
                else:
                    result[tag] = [result[tag], value]
            else:
                result[tag] = value

        text = direct_text(element)
        if text is not None:
            result["#text"] = text

        return result

    return {root.tag: convert(root)}
