import math
from numbers import Real


def row_averages_and_correlations(data):
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")

    if len(data) == 0:
        return ([], [])

    if not all(isinstance(row, list) for row in data):
        raise ValueError("data must be a rectangular list of rows")

    n_rows = len(data)
    n_cols = len(data[0])

    if n_cols == 0:
        raise ValueError("rows must contain at least one number")

    for row in data:
        if len(row) != n_cols:
            raise ValueError("data must be rectangular")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise ValueError("data must contain only numbers")

    averages = [sum(row) / n_cols for row in data]

    column_means = [
        sum(data[i][j] for i in range(n_rows)) / n_rows
        for j in range(n_cols)
    ]

    variances = []
    for j in range(n_cols):
        col = [data[i][j] for i in range(n_rows)]
        mean = column_means[j]

        if all(value == col[0] for value in col):
            variances.append(0.0)
        else:
            variances.append(
                sum((value - mean) ** 2 for value in col) / n_rows
            )

    std_devs = [math.sqrt(v) for v in variances]

    corr = [[0.0 for _ in range(n_cols)] for _ in range(n_cols)]

    for i in range(n_cols):
        corr[i][i] = 1.0

        for j in range(i + 1, n_cols):
            if std_devs[i] == 0.0 or std_devs[j] == 0.0:
                correlation = 0.0
            else:
                covariance = (
                    sum(
                        (data[k][i] - column_means[i])
                        * (data[k][j] - column_means[j])
                        for k in range(n_rows)
                    )
                    / n_rows
                )
                correlation = covariance / (std_devs[i] * std_devs[j])

                correlation = max(-1.0, min(1.0, correlation))

            corr[i][j] = correlation
            corr[j][i] = correlation

    return averages, corr
