from datetime import date, datetime, timedelta


def daily_sales_totals(dates, sales):
    if len(dates) != len(sales):
        raise ValueError("dates and sales must have the same length")
    if not dates:
        raise ValueError("no records")

    def parse_day(value):
        value = value.strip()
        if value.endswith("Z"):
            value = value[:-1] + "+00:00"
        try:
            return datetime.fromisoformat(value).date()
        except ValueError:
            return date.fromisoformat(value)

    totals = {}
    earliest = None
    latest = None

    for date_string, amount in zip(dates, sales):
        day = parse_day(date_string)

        totals[day] = totals.get(day, 0) + amount

        if earliest is None or day < earliest:
            earliest = day
        if latest is None or day > latest:
            latest = day

    result = []
    current = earliest
    one_day = timedelta(days=1)

    while current <= latest:
        result.append((current.isoformat(), totals.get(current, 0)))
        current += one_day

    return result
