def quartiles_of_string_groups(groups):
    values = sorted(int(value) for group in groups for value in group)

    if not values:
        raise ValueError("Cannot compute quartiles of an empty collection")

    def percentile(p):
        rank = (len(values) - 1) * p
        lower = int(rank)
        upper = min(lower + 1, len(values) - 1)
        fraction = rank - lower
        return float(values[lower] + (values[upper] - values[lower]) * fraction)

    return (
        percentile(0.25),
        percentile(0.50),
        percentile(0.75),
    )
