    for col, values in encoded.items():
        n = len(values)
        mean = sum(values) / n
        sample_variance = sum((x - mean) ** 2 for x in values) / (n - 1)
        std = math.sqrt(sample_variance)
        result[col] = [(x - mean) / std for x in values]

