from math import sqrt

def standardize_and_correlate(rows):
    n = len(rows)
    if n == 0:
        return [], []

    p = len(rows[0])

    # Column means using only observed values
    means = []
    for j in range(p):
        observed = [row[j] for row in rows if row[j] is not None]
        means.append(sum(observed) / len(observed) if observed else 0.0)

    # Replace missing values with their column mean
    filled = [
        [means[j] if row[j] is None else row[j] for j in range(p)]
        for row in rows
    ]

    # Population means and standard deviations after imputation
    mus = []
    stds = []
    for j in range(p):
        col = [filled[i][j] for i in range(n)]
        mu = sum(col) / n
        mus.append(mu)

        variance = sum((x - mu) ** 2 for x in col) / n
        stds.append(sqrt(variance) if variance > 0 else 0.0)

    # Standardize
    standardized = []
    for row in filled:
        standardized.append([
            (row[j] - mus[j]) / stds[j] if stds[j] > 0 else 0.0
            for j in range(p)
        ])

    # Pearson correlation matrix
    corr = []
    for j in range(p):
        corr_row = []
        for k in range(p):
            if stds[j] == 0.0 or stds[k] == 0.0:
                value = 1.0 if j == k else 0.0
            else:
                value = sum(
                    standardized[i][j] * standardized[i][k]
                    for i in range(n)
                ) / n

                if j == k:
                    value = 1.0
                elif value > 1.0:
                    value = 1.0
                elif value < -1.0:
                    value = -1.0

            corr_row.append(value)
        corr.append(corr_row)

    return standardized, corr
