import math
import numbers

def correlation_without_column(data, column):
    def is_number(v):
        if isinstance(v, bool) or not isinstance(v, numbers.Real):
            return False
        if isinstance(v, float):
            return math.isfinite(v)
        return True

    cols = {}
    for name, values in data.items():
        if name == column:
            continue
        if all(is_number(v) for v in values):
            cols[name] = values

    if not cols:
        return None

    n = len(next(iter(cols.values())))
    if n == 0:
        return None

    means = {name: sum(values) / n for name, values in cols.items()}
    devs = {name: [v - means[name] for v in values] for name, values in cols.items()}
    sumsq = {name: sum(d * d for d in devs[name]) for name in cols}

    result = {}

    for x in cols:
        result[x] = {}
        for y in cols:
            if x == y:
                result[x][y] = float("nan") if sumsq[x] == 0 else 1.0
            else:
                denom = math.sqrt(sumsq[x] * sumsq[y])
                if denom == 0:
                    result[x][y] = float("nan")
                else:
                    cov = sum(a * b for a, b in zip(devs[x], devs[y]))
                    result[x][y] = cov / denom

    return result
