def zscores_by_date(rows):
    if not rows:
        return []

    n_rows = len(rows)
    n_cols = len(rows[0][1])

    means = [0.0] * n_cols
    for _, values in rows:
        for i, value in enumerate(values):
            means[i] += value

    means = [total / n_rows for total in means]

    variances = [0.0] * n_cols
    for _, values in rows:
        for i, value in enumerate(values):
            diff = value - means[i]
            variances[i] += diff * diff

    stddevs = [(variance / n_rows) ** 0.5 for variance in variances]

    result = []
    for date, values in rows:
        z_values = []
        for i, value in enumerate(values):
            if stddevs[i] == 0:
                z_values.append(0.0)
            else:
                z_values.append((value - means[i]) / stddevs[i])
        result.append([date] + z_values)

    return result
