def replace_and_standardize(data, features, mapping):
    missing = [feature for feature in features if feature not in data]
    if missing:
        raise ValueError(f"Missing feature columns: {missing}")

    # Apply replacements to every value in every column, preserving column order.
    result = {
        column: [mapping.get(value, value) for value in values]
        for column, values in data.items()
    }

    # Standardize only the requested feature columns.
    for feature in features:
        values = result[feature]
        n = len(values)

        if n == 0:
            result[feature] = []
            continue

        mean = sum(values) / n
        variance = sum((value - mean) ** 2 for value in values) / n
        std = variance ** 0.5

        if std == 0:
            result[feature] = [0.0 for _ in values]
        else:
            result[feature] = [(value - mean) / std for value in values]

