def _jacobi_eigen(A):
    m = len(A)
    A = [row[:] for row in A]
    V = [[1.0 if i == j else 0.0 for j in range(m)] for i in range(m)]

    for _ in range(100):
        max_val = 0.0
        p = q = 0
        for i in range(m):
            for j in range(i + 1, m):
                val = abs(A[i][j])
                if val > max_val:
                    max_val = val
                    p, q = i, j

        if max_val < 1e-15:
            break

        app = A[p][p]
        aqq = A[q][q]
        apq = A[p][q]
        if apq == 0.0:
            continue

        theta = (aqq - app) / (2.0 * apq)
        if theta == 0.0:
            t = 1.0
        else:
            t = (1.0 if theta > 0.0 else -1.0) / (
                abs(theta) + (theta * theta + 1.0) ** 0.5
            )

        c = 1.0 / (t * t + 1.0) ** 0.5
        s = t * c

        G = [[1.0 if i == j else 0.0 for j in range(m)] for i in range(m)]
        G[p][p] = c
        G[q][q] = c
        G[p][q] = s
        G[q][p] = -s

        # A = G^T A G
        temp = [[0.0] * m for _ in range(m)]
        for i in range(m):
            for j in range(m):
                temp[i][j] = sum(A[i][k] * G[k][j] for k in range(m))

        newA = [[0.0] * m for _ in range(m)]
        for i in range(m):
            for j in range(m):
                newA[i][j] = sum(G[k][i] * temp[k][j] for k in range(m))
        A = newA

        # V = V G
        newV = [[0.0] * m for _ in range(m)]
        for i in range(m):
            for j in range(m):
                newV[i][j] = sum(V[i][k] * G[k][j] for k in range(m))
        V = newV

    eigenvalues = [A[i][i] for i in range(m)]
    return eigenvalues, V


def fit_linear_regression(rows):
    if not rows:
        raise ValueError("rows must not be empty")

    for row in rows:
        if len(row) != 5:
            raise ValueError("each row must contain exactly five values")

    n = len(rows)
    X = []
    y = []

    for row in rows:
        X.append([
            1.0,
            float(row[0]),
            float(row[1]),
            float(row[2]),
            float(row[3]),
        ])
        y.append(float(row[4]))

    p = 5
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for i in range(n):
        xi = X[i]
        yi = y[i]
        for j in range(p):
            b[j] += xi[j] * yi
            for k in range(p):
                A[j][k] += xi[j] * xi[k]

    eigenvalues, V = _jacobi_eigen(A)

    max_lam = max(abs(v) for v in eigenvalues)
    tol = 1e-12 * max(1.0, max_lam)

    beta = [0.0] * p
    for idx, lam in enumerate(eigenvalues):
        if lam > tol:
            v = [V[i][idx] for i in range(p)]
            c = sum(v[i] * b[i] for i in range(p))
            factor = c / lam
            for i in range(p):
                beta[i] += factor * v[i]

    y_pred = [
        sum(X[i][j] * beta[j] for j in range(p))
        for i in range(n)
    ]

    sse = sum((y[i] - y_pred[i]) ** 2 for i in range(n))
    mean_y = sum(y) / n
    sst = sum((y[i] - mean_y) ** 2 for i in range(n))

    if sst < 1e-12:
        r_squared = 1.0 if sse < 1e-12 else 0.0
    else:
        r_squared = 1.0 - sse / sst

    return beta, r_squared
