    if reader.fieldnames is None:
        raise ValueError("CSV must contain a header row")
    if date_column not in reader.fieldnames:
        raise ValueError(f"Missing date column: {date_column}")

    counts = Counter()

    for row_number, row in enumerate(reader, start=2):
        value = row.get(date_column)

        if value is None or not value.strip():
            raise ValueError(f"Invalid date in row {row_number}: {value!r}")

        try:
            year = parser.parse(value.strip(), fuzzy=False).year
        except (ValueError, TypeError, OverflowError) as exc:
            raise ValueError(f"Invalid date in row {row_number}: {value!r}") from exc

        counts[year] += 1

    return dict(counts)
