import xml.etree.ElementTree as ET

def xml_to_dict(s):
    if not s or not s.strip():
        raise ValueError("XML input is empty or only whitespace")

    try:
        root = ET.fromstring(s)
    except ET.ParseError as e:
        raise ValueError(f"Invalid XML: {e}") from e

    def parse(elem):
        children = list(elem)

        # Collect direct text and text following child elements.
        text_parts = []
        if elem.text:
            t = elem.text.strip()
            if t:
                text_parts.append(t)

        for child in children:
            if child.tail:
                t = child.tail.strip()
                if t:
                    text_parts.append(t)

        text = "".join(text_parts) if text_parts else None

        # Element with only text, or empty element.
        if not elem.attrib and not children:
            return text

        result = {}

        for key, value in elem.attrib.items():
            result["@" + key] = value

        for child in children:
            tag = child.tag
            value = parse(child)

            if tag in result:
                if isinstance(result[tag], list):
                    result[tag].append(value)
                else:
                    result[tag] = [result[tag], value]
            else:
                result[tag] = value

        if text is not None:
            result["#text"] = text

        return result

    return {root.tag: parse(root)}
