```python
def dbscan_cluster_labels(points):
    n = len(points)
    eps_sq = 3 * 3
    min_samples = 2

    labels = [None] * n
    visited = [False] * n

    def neighbors(i):
        result = []
        pi = points[i]
        for j, pj in enumerate(points):
            dist_sq = 0
            for a, b in zip(pi, pj):
                d = a - b
                dist_sq += d * d
            if dist_sq <= eps_sq:
                result.append(j)
        return result

    cluster_id = 0

    for i in range(n):
        if visited[i]:
            continue

        visited[i] = True
        neigh = neighbors(i)

        if len(neigh) < min_samples:
            labels[i] = -1
        else:
            labels[i] = cluster_id
            seeds = list(neigh)
            k = 0

            while k < len(seeds):
                q = seeds[k]
                k += 1

                if not visited[q]:
                    visited[q] = True
                    q_neigh = neighbors(q)
                    if len(q_neigh) >= min_samples:
                        seeds.extend(q_neigh)

                if labels[q] is None or labels[q] == -1:
                    labels[q] = cluster_id

            cluster_id += 1

    return [-1 if label is None else label for label in labels]
