from html.parser import HTMLParser


class _TableRecordsParser(HTMLParser):
    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)
        self.table_id = table_id
        self.table_stack = []
        self.found = False

        self.rows = []
        self.current_row = None
        self.row_table_level = None

        self.current_cell_parts = None
        self.cell_table_level = None

    def _in_target_directly(self):
        return bool(self.table_stack) and self.table_stack[-1]["is_target"]

    def _finish_cell(self):
        if self.current_cell_parts is not None:
            text = "".join(self.current_cell_parts).strip()
            if self.current_row is not None:
                self.current_row.append(text)
            self.current_cell_parts = None
            self.cell_table_level = None

    def _finish_row(self):
        if self.current_cell_parts is not None:
            self._finish_cell()
        if self.current_row is not None:
            self.rows.append(self.current_row)
        self.current_row = None
        self.row_table_level = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if tag == "table":
            attrs = dict(attrs)
            is_target = not self.found and attrs.get("id") == self.table_id
            self.table_stack.append({"is_target": is_target})
            if is_target:
                self.found = True
            return

        if tag == "tr":
            if self._in_target_directly():
                if self.current_row is not None:
                    self._finish_row()
                self.current_row = []
                self.row_table_level = len(self.table_stack)
            return

        if tag in ("td", "th"):
            if self._in_target_directly():
                if self.current_cell_parts is not None:
                    self._finish_cell()
                self.current_cell_parts = []
                self.cell_table_level = len(self.table_stack)
            return

    def handle_endtag(self, tag):
        tag = tag.lower()

        if tag in ("td", "th"):
            if (
                self.current_cell_parts is not None
                and self.cell_table_level == len(self.table_stack)
            ):
                self._finish_cell()
            return

        if tag == "tr":
            if (
                self.current_row is not None
                and self.row_table_level == len(self.table_stack)
            ):
                self._finish_row()
            return

        if tag == "table":
            if (
                self.current_cell_parts is not None
                and self.cell_table_level == len(self.table_stack)
            ):
                self._finish_cell()

            if (
                self.current_row is not None
                and self.row_table_level == len(self.table_stack)
            ):
                self._finish_row()

            if self.table_stack:
                self.table_stack.pop()

    def handle_data(self, data):
        if self.current_cell_parts is not None:
            self.current_cell_parts.append(data)


def html_table_records(html, table_id):
    parser = _TableRecordsParser(table_id)
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError(f"No table found with id {table_id!r}")

    if not parser.rows:
        return []

    headers = parser.rows[0]
    records = []

    for row in parser.rows[1:]:
        record = {}
        for i, header in enumerate(headers):
            record[header] = row[i] if i < len(row) else ""
        records.append(record)

    return records
