import math

def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    # Apply value mapping to each column.
    columns = {
        name: [mapping[v] if v in mapping else v for v in values]
        for name, values in data.items()
    }

    result = {}

    for a, xs in columns.items():
        result[a] = {}

        for b, ys in columns.items():
            if a == b:
                result[a][b] = 1.0
                continue

            n = len(xs)
            mean_x = sum(xs) / n
            mean_y = sum(ys) / n

            covariance = sum(
                (x - mean_x) * (y - mean_y)
                for x, y in zip(xs, ys)
            )
            variance_x = sum((x - mean_x) ** 2 for x in xs)
            variance_y = sum((y - mean_y) ** 2 for y in ys)

            denominator = math.sqrt(variance_x * variance_y)
            result[a][b] = (
                covariance / denominator
                if denominator != 0
                else float("nan")
            )

    return result
