    reader = csv.reader(io.StringIO(csv_text))

    # Skip the header row
    next(reader, None)

    for row in reader:
        if not row:
            continue

        value = row[0].strip()
        if not value:
            continue

        try:
            numbers.append(float(value))
        except ValueError:
            continue

    if not numbers:
        return (None, None)

    n = len(numbers)
    mean = sum(numbers) / n

    numbers.sort()
    mid = n // 2

    if n % 2 == 1:
        median = float(numbers[mid])
    else:
        median = (numbers[mid - 1] + numbers[mid]) / 2.0

    return (mean, median)
