def country_score_summary(records):
    if not records:
        raise ValueError("records must not be empty")

    required = {"Name", "Country", "Score"}
    seen_names = set()
    scores_by_country = {}

    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError("Each record must contain 'Name', 'Country', and 'Score'")

        name = record["Name"]
        if name in seen_names:
            continue

        seen_names.add(name)
        country = record["Country"]
        score = record["Score"]

        scores_by_country.setdefault(country, []).append(score)

    def percentile(sorted_values, p):
        if len(sorted_values) == 1:
            return float(sorted_values[0])

        position = (len(sorted_values) - 1) * p
        lower = int(position)
        upper = min(lower + 1, len(sorted_values) - 1)
        fraction = position - lower

        return (
            sorted_values[lower] * (1 - fraction)
            + sorted_values[upper] * fraction
        )

    result = {}

    for country, scores in scores_by_country.items():
        sorted_scores = sorted(scores)

        result[country] = [
            float(sorted_scores[0]),
            float(percentile(sorted_scores, 0.25)),
            float(percentile(sorted_scores, 0.50)),
            float(percentile(sorted_scores, 0.75)),
            float(sorted_scores[-1]),
        ]

    return result
