from numbers import Number
from decimal import Decimal


def column_covariance(columns):
    if not columns:
        raise ValueError("table has no columns")

    names = list(columns)
    n = len(columns[names[0]])

    if n == 0:
        raise ValueError("table has no rows")
    if n < 2:
        raise ValueError("at least two rows are required")

    for name in names:
        col = columns[name]

        if len(col) != n:
            raise ValueError("all columns must have the same length")

        for value in col:
            if not isinstance(value, (Number, Decimal)):
                raise TypeError(f"non-numeric value in column {name!r}: {value!r}")

    means = {name: sum(columns[name]) / n for name in names}

    result = {}
    for a in names:
        result[a] = {}
        for b in names:
            covariance = sum(
                (x - means[a]) * (y - means[b])
                for x, y in zip(columns[a], columns[b])
            ) / (n - 1)
            result[a][b] = covariance

    return result
