def _sqdist(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b))


def _mean(points, indices):
    dim = len(points[0])
    return [
        sum(points[i][d] for i in indices) / len(indices)
        for d in range(dim)
    ]


def cluster_point_indices(points, n_clusters):
    n = len(points)

    if n_clusters <= 0:
        return []
    if n == 0:
        raise ValueError("points must not be empty")
    if n_clusters > n:
        raise ValueError("n_clusters cannot exceed the number of points")
    if n_clusters == 1:
        return [list(range(n))]
    if n_clusters == n:
        return [[i] for i in range(n)]

    # Deterministic initialization: first point, then points farthest from existing centers.
    centroids = [list(points[0])]
    chosen = {0}

    while len(centroids) < n_clusters:
        best_i = None
        best_dist = -1.0

        for i in range(n):
            if i in chosen:
                continue
            d = min(_sqdist(points[i], c) for c in centroids)
            if d > best_dist:
                best_dist = d
                best_i = i

        if best_i is None:
            best_i = next(i for i in range(n) if i not in chosen)

        centroids.append(list(points[best_i]))
        chosen.add(best_i)

    labels = None

    for _ in range(100):
        new_labels = []

        for p in points:
            best_j = 0
            best_d = _sqdist(p, centroids[0])

            for j in range(1, n_clusters):
                d = _sqdist(p, centroids[j])
                if d < best_d:
                    best_d = d
                    best_j = j

            new_labels.append(best_j)

        counts = [0] * n_clusters
        for label in new_labels:
            counts[label] += 1

        # Ensure every cluster is non-empty.
        for empty in [j for j in range(n_clusters) if counts[j] == 0]:
            best_i = None
            best_old = None
            best_d = -1.0

            for old in range(n_clusters):
                if counts[old] <= 1:
                    continue

                members = [i for i, label in enumerate(new_labels) if label == old]
                mean = _mean(points, members)

                for i in members:
                    d = _sqdist(points[i], mean)
                    if d > best_d:
                        best_d = d
                        best_i = i
                        best_old = old

            if best_i is not None:
                new_labels[best_i] = empty
                counts[empty] += 1
                counts[best_old] -= 1

        if new_labels == labels:
            labels = new_labels
            break

        labels = new_labels
        centroids = [
            _mean(points, [i for i, label in enumerate(labels) if label == j])
            for j in range(n_clusters)
        ]

    clusters = [[] for _ in range(n_clusters)]
    for i, label in enumerate(labels):
        clusters[label].append(i)

    for cluster in clusters:
        cluster.sort()

    clusters.sort(key=lambda cluster: cluster[0])
    return clusters
```

