import json
import math


def numeric_correlation_from_json(json_text):
    try:
        data = json.loads(json_text)
    except (json.JSONDecodeError, TypeError) as exc:
        raise ValueError("Invalid JSON") from exc

    if not isinstance(data, dict) or not data:
        raise ValueError("Data is empty or not a JSON object")

    numeric_cols = {}
    for name, values in data.items():
        if not isinstance(values, list):
            continue

        # Treat only actual numbers as numeric; JSON booleans are not numeric.
        if all(
            isinstance(v, (int, float)) and not isinstance(v, bool)
            for v in values
        ):
            numeric_cols[name] = [float(v) for v in values]

    if not numeric_cols:
        return {}

    lengths = {len(values) for values in numeric_cols.values()}
    if len(lengths) != 1:
        raise ValueError("Numeric columns must have equal length")

    n = next(iter(lengths))
    if n == 0:
        raise ValueError("Data is empty")

    columns = list(numeric_cols)

    stats = {}
    for col in columns:
        values = numeric_cols[col]
        mean = sum(values) / n
        deviations = [v - mean for v in values]
        variance_sum = sum(d * d for d in deviations)
        stats[col] = (deviations, variance_sum)

    result = {}

    for x in columns:
        dx, variance_x = stats[x]
        row = {}

        for y in columns:
            if x == y:
                row[y] = 1.0
                continue

            dy, variance_y = stats[y]
            denominator = math.sqrt(variance_x * variance_y)

            if denominator == 0.0:
                row[y] = 0.0
            else:
                covariance = sum(dx[i] * dy[i] for i in range(n))
                correlation = covariance / denominator

                # Protect against tiny floating-point overshoots.
                correlation = max(-1.0, min(1.0, correlation))
                row[y] = correlation

        result[x] = row

    return result
