import math

def standardize_columns(data):
    if not data:
        return []

    n_rows = len(data)
    n_cols = len(data[0])

    if n_cols == 0:
        return [list(row) for row in data]

    means = [0.0] * n_cols
    for row in data:
        for j, value in enumerate(row):
            means[j] += value

    means = [total / n_rows for total in means]

    variances = [0.0] * n_cols
    for row in data:
        for j, value in enumerate(row):
            diff = value - means[j]
            variances[j] += diff * diff

    stds = [math.sqrt(total / n_rows) for total in variances]

    result = []
    for row in data:
        standardized_row = []
        for j, value in enumerate(row):
            if stds[j] == 0.0:
                standardized_row.append(0.0)
            else:
                standardized_row.append((value - means[j]) / stds[j])
        result.append(standardized_row)

    return result
