import math
from collections import Counter


def tfidf_matrix(documents):
    def tokenize(text):
        tokens = []
        current = []
        for ch in text.lower():
            if ch.isalnum():
                current.append(ch)
            elif current:
                tokens.append("".join(current))
                current = []
        if current:
            tokens.append("".join(current))
        return tokens

    doc_counts = []
    df = {}

    for doc in documents:
        counts = Counter(tokenize(doc))
        doc_counts.append(counts)
        for word in counts:
            df[word] = df.get(word, 0) + 1

    words = sorted(df)
    n = len(documents)

    idf = {
        word: math.log((1 + n) / (1 + df[word])) + 1
        for word in words
    }

    rows = []
    for counts in doc_counts:
        row = [counts.get(word, 0) * idf[word] for word in words]
        norm = math.sqrt(sum(score * score for score in row))
        if norm != 0:
            row = [score / norm for score in row]
        rows.append(row)

    return words, rows
