def complete_row_histogram(data, bins):
    cleaned = {name: [] for name in data}

    if not data:
        return cleaned, None

    columns = list(data.keys())
    row_count = len(data[columns[0]])

    for i in range(row_count):
        if any(data[col][i] is None for col in columns):
            continue

        for col in columns:
            cleaned[col].append(float(data[col][i]))

    values = []
    for col in columns:
        values.extend(cleaned[col])

    if not values:
        return cleaned, None

    lo = min(values)
    hi = max(values)

    if lo == hi:
        return cleaned, None

    counts = [0] * bins
    width = (hi - lo) / bins

    for value in values:
        if value == hi:
            index = bins - 1
        else:
            index = int((value - lo) / width)
            index = max(0, min(index, bins - 1))
        counts[index] += 1

    return cleaned, counts
