import math
import random

def cluster_labels(rows):
    if not rows:
        return []

    n = len(rows)
    m = len(rows[0])

    # Standardize each column to zero mean and unit variance.
    means = [sum(row[j] for row in rows) / n for j in range(m)]
    stds = []
    for j in range(m):
        var = sum((row[j] - means[j]) ** 2 for row in rows) / n
        std = math.sqrt(var)
        stds.append(std if std != 0 else 1.0)

    X = [[(row[j] - means[j]) / stds[j] for j in range(m)] for row in rows]

    # K-means with k-means++ initialization (deterministic seed).
    rng = random.Random(0)
    centroids = [X[rng.randrange(n)][:]]

    for _ in range(1, 3):
        d2 = []
        for x in X:
            d2.append(min(
                sum((x[j] - c[j]) ** 2 for j in range(m))
                for c in centroids
            ))

        total = sum(d2)
        if total == 0:
            centroids.append(X[len(centroids) % n][:])
        else:
            r = rng.random() * total
            acc = 0.0
            for i, val in enumerate(d2):
                acc += val
                if acc >= r:
                    centroids.append(X[i][:])
                    break
            else:
                centroids.append(X[-1][:])

    labels = [-1] * n
    for _ in range(100):
        new_labels = []
        for x in X:
            best = 0
            best_dist = sum((x[j] - centroids[0][j]) ** 2 for j in range(m))
            for k in range(1, 3):
                dist = sum((x[j] - centroids[k][j]) ** 2 for j in range(m))
                if dist < best_dist:
                    best_dist = dist
                    best = k
            new_labels.append(best)

        new_centroids = []
        for k in range(3):
            pts = [X[i] for i in range(n) if new_labels[i] == k]
            if pts:
                new_centroids.append([
                    sum(p[j] for p in pts) / len(pts) for j in range(m)
                ])
            else:
                new_centroids.append(centroids[k][:])

        if new_labels == labels:
            labels = new_labels
            break

        labels = new_labels
        centroids = new_centroids

    # Renumber clusters by first appearance.
    mapping = {}
    result = []
    for label in labels:
        if label not in mapping:
            mapping[label] = len(mapping)
        result.append(mapping[label])

    return result
```

