def normalize_columns(data):
    if not data:
        raise ValueError("data must not be empty")

    normalized = {}

    for column, values in data.items():
        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(f"Column {column!r} contains a non-numeric value: {value!r}")

        if not values:
            normalized[column] = []
            continue

        minimum = min(values)
        maximum = max(values)

        if minimum == maximum:
            normalized[column] = [0.0] * len(values)
        else:
            span = float(maximum - minimum)
            normalized[column] = [
                float(value - minimum) / span for value in values
            ]

    return normalized
