from html.parser import HTMLParser


class _FirstTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found = False
        self.done = False
        self.table_depth = 0

        self.headers = []
        self.rows = []

        self.current_row = None
        self.current_cell = None
        self.current_cell_type = None

    def _finish_cell(self):
        if self.current_cell is None:
            return

        text = "".join(self.current_cell).strip()

        if self.current_cell_type == "th":
            self.headers.append(text)
        elif self.current_cell_type == "td" and self.current_row is not None:
            self.current_row.append(text)

        self.current_cell = None
        self.current_cell_type = None

    def _finish_row(self):
        if self.current_row is not None:
            if self.current_row:
                self.rows.append(self.current_row)
            self.current_row = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if self.done:
            return

        if tag == "table":
            if not self.found:
                self.found = True
                self.table_depth = 1
            else:
                self.table_depth += 1
            return

        if not self.found or self.table_depth == 0:
            return

        if self.table_depth == 1:
            if tag == "tr":
                self._finish_cell()
                self._finish_row()
                self.current_row = []
            elif tag in ("td", "th"):
                self._finish_cell()
                self.current_cell = []
                self.current_cell_type = tag

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        tag = tag.lower()

        if self.done:
            return

        if tag == "table":
            if not self.found:
                return

            if self.table_depth == 1:
                self._finish_cell()
                self._finish_row()
                self.done = True
                self.table_depth = 0
            elif self.table_depth > 1:
                self.table_depth -= 1
            return

        if not self.found or self.table_depth == 0:
            return

        if self.table_depth == 1:
            if tag in ("td", "th"):
                if self.current_cell_type == tag:
                    self._finish_cell()
            elif tag == "tr":
                self._finish_cell()
                self._finish_row()

    def handle_data(self, data):
        if self.done:
            return

        if self.found and self.table_depth >= 1 and self.current_cell is not None:
            self.current_cell.append(data)


def extract_first_table(html):
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()

    parser._finish_cell()
    parser._finish_row()

    if not parser.found:
        raise ValueError("No table found")

    if not parser.rows:
        raise ValueError("No data rows found")

    return parser.headers, parser.rows
```

