import math

def timestamp_dates_and_histogram(timestamps):
    if not timestamps:
        raise ValueError("timestamps must not be empty")

    dates = [
        datetime.fromtimestamp(ts, tz=timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
        for ts in timestamps
    ]

    lo = min(timestamps)
    hi = max(timestamps)
    counts = [0] * 10

    if lo == hi:
        counts[-1] = len(timestamps)
        return dates, counts

    span = hi - lo

    for ts in timestamps:
        if ts == hi:
            idx = 9
        else:
            if all(isinstance(v, int) for v in (ts, lo, span)):
                idx = ((ts - lo) * 10) // span
            else:
                idx = math.floor((ts - lo) * 10 / span)

        idx = max(0, min(9, idx))
        counts[idx] += 1

    return dates, counts
