def _natural_sort_key(name):
    return [
        int(part) if part.isdigit() else part.lower()
        for part in re.split(r'(\d+)', name)
    ]


def extract_matches_from_files(files, name_pattern, value_pattern):
    selected = [
        filename for filename in files
        if fnmatch.fnmatch(filename, name_pattern)
    ]

    if not selected:
        raise ValueError("No file name matches the wildcard pattern")

    selected.sort(key=_natural_sort_key)

    result = []
    for filename in selected:
        matches = re.findall(value_pattern, files[filename])
        result.append((filename, matches))

    return result
