import math

def highly_correlated_column_pairs(data, cols, threshold):
    if threshold < 0 or threshold > 1:
        raise ValueError("threshold must be between 0 and 1")

    n = len(data)
    m = len(cols)

    if n < 2:
        return []

    columns = [[row[i] for row in data] for i in range(m)]

    # Constant columns have undefined Pearson correlation, so skip them.
    constant = [max(col) == min(col) for col in columns]

    centered = []
    variances = []

    for col, is_constant in zip(columns, constant):
        if is_constant:
            centered.append(None)
            variances.append(0.0)
        else:
            mean = math.fsum(col) / n
            diffs = [x - mean for x in col]
            centered.append(diffs)
            variances.append(math.fsum(d * d for d in diffs))

    pairs = []

    for i in range(m):
        if constant[i]:
            continue

        for j in range(i + 1, m):
            if constant[j]:
                continue

            cov = math.fsum(a * b for a, b in zip(centered[i], centered[j]))
            denom = math.sqrt(variances[i] * variances[j])

            if denom == 0:
                continue

            correlation = abs(cov / denom)

            if correlation > threshold:
                pairs.append((cols[i], cols[j]))

    return pairs
