def attribute_histogram(records, key, num_bins=30):
    if num_bins <= 0:
        raise ValueError("num_bins must be positive")

    values = [float(record[key]) for record in records]

    if not values:
        return [0] * num_bins, [float(i) for i in range(num_bins + 1)]

    lo = min(values)
    hi = max(values)

    if lo == hi:
        left = hi - 1.0
        right = hi
    else:
        left = lo
        right = hi

    width = (right - left) / num_bins
    edges = [left + i * width for i in range(num_bins + 1)]
    edges[-1] = right

    counts = [0] * num_bins

    for value in values:
        if value == hi:
            idx = num_bins - 1
        else:
            idx = int((value - left) / width)
            if idx < 0:
                idx = 0
            elif idx >= num_bins:
                idx = num_bins - 1

        counts[idx] += 1

    return counts, edges
