import csv
import io
import math
import re

_NUM_RE = re.compile(
    r'^[+-]?(?:(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$'
)


def _parse_number(text):
    s = text.strip()
    if not s or not _NUM_RE.fullmatch(s):
        return None
    try:
        return float(s.replace(",", ""))
    except ValueError:
        return None


def summarize_numeric_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    header = next(reader, None)

    if header is None:
        return {"means": {}, "std_devs": {}, "f_value": None}

    if header:
        header[0] = header[0].lstrip("\ufeff")

    ncols = len(header)
    values = [[] for _ in range(ncols)]
    invalid = [False] * ncols

    for row in reader:
        if len(row) == 0:
            continue

        for i in range(ncols):
            if invalid[i]:
                continue

            if i >= len(row):
                invalid[i] = True
                continue

            number = _parse_number(row[i])
            if number is None:
                invalid[i] = True
            else:
                values[i].append(number)

    means = {}
    std_devs = {}
    groups = []

    for i in range(ncols):
        if invalid[i] or not values[i]:
            continue

        vals = values[i]
        n = len(vals)
        mean = sum(vals) / n
        name = header[i]

        means[name] = mean

        if n >= 2:
            variance = sum((x - mean) ** 2 for x in vals) / (n - 1)
            std_devs[name] = math.sqrt(variance)
        else:
            std_devs[name] = None

        groups.append(vals)

    f_value = None
    k = len(groups)

    if k >= 2:
        n_total = sum(len(group) for group in groups)
        grand_mean = sum(sum(group) for group in groups) / n_total

        ss_between = 0.0
        ss_within = 0.0

        for group in groups:
            n = len(group)
            mean = sum(group) / n

            ss_between += n * (mean - grand_mean) ** 2
            ss_within += sum((x - mean) ** 2 for x in group)

        df_between = k - 1
        df_within = n_total - k

        if df_within > 0:
            ms_between = ss_between / df_between
            ms_within = ss_within / df_within

            if ms_within == 0:
                f_value = None if ms_between == 0 else float("inf")
            else:
                f_value = ms_between / ms_within

    return {
        "means": means,
        "std_devs": std_devs,
        "f_value": f_value,
    }
