        variance = sum((x - mean) ** 2 for x in values) / n
        std = variance ** 0.5

        if std == 0.0:
            standardized = [0.0] * n
        else:
            standardized = [(x - mean) / std for x in values]

        minimum = min(standardized)
        maximum = max(standardized)
        counts = [0] * 20

        if minimum == maximum:
            counts[19] = n
        else:
            width = (maximum - minimum) / 20.0

            for value in standardized:
                if value == maximum:
                    index = 19
                else:
                    index = int((value - minimum) / width)
                    if index < 0:
                        index = 0
                    elif index >= 20:
                        index = 19

                counts[index] += 1

        result[column] = (standardized, counts)

