        raise ValueError("no numeric columns")
    if n == 0:
        raise ValueError("table is empty")

    standardized = {}
    centered = {}
    sq_sums = {}

    for c in columns:
        values = table[c]

        if c in numeric_columns:
            mean = sum(values) / n
            centered_values = [v - mean for v in values]
            variance = sum(v * v for v in centered_values) / n
            std = sqrt(variance)

            centered[c] = centered_values
            sq_sums[c] = sum(v * v for v in centered_values)

            if std == 0:
                standardized[c] = [0.0 for _ in values]
            else:
                standardized[c] = [v / std for v in centered_values]
        else:
            standardized[c] = list(values)

    size = len(numeric_columns)
    corr = [[0.0] * size for _ in range(size)]

    for i, ci in enumerate(numeric_columns):
        for j, cj in enumerate(numeric_columns):
            if i == j:
                corr[i][j] = 1.0
            elif sq_sums[ci] == 0 or sq_sums[cj] == 0:
                corr[i][j] = 0.0
            else:
                numerator = sum(a * b for a, b in zip(centered[ci], centered[cj]))
                denominator = sqrt(sq_sums[ci] * sq_sums[cj])
                corr[i][j] = numerator / denominator

    return standardized, corr
```

